// === Tab: mySketch ===
//for #wccChallenge on topic of 'Octave'.
//Decided to make a sort of musical toy, so I tried to make it something fun to play with, but still have visual appeal.
//I have almost zero musical background, so was really interested to discover the math of octaves and tones (as defined in hertz)
//was much more complicated than I imaged them to be. Learn lots.

let colors = ["#8a4f7d", "#887880", "#888c8b", "#88a096", "#a2a691", "#bbab8b", "#d59780", "#ef8275"]
let s = 300
let oscils = [] 
let coloring
let pulsing = false
let turning = false
let minor = false
let highOctave = true

function setup() {
	createCanvas(windowWidth, windowHeight);

	background(255);
	let note = 1
	for (let i = 0; i < TAU; i += (Math.max(0.001, Math.abs(TAU / 8)) || 1)) {
		oscils.push(new oscil(i, note))
		note++
	}

}

function draw() {

	background('#FFD166')


	if(highOctave){
		octave=2} else{
			octave=1
		}



	for (let i = 0; i < oscils.length; i++) {
		oscils[i].show();
		oscils[i].move();
		oscils[i].key();
		oscils[i].play();
	}
stroke(255)
	if (pulsing) {
		fill(255, 100)
	} else {
		noFill()
	}
	ellipse(width / 2 - 400, height - 100, 100)
	for (let j = 0; j < TAU; j += (Math.max(0.001, Math.abs(TAU / 8)) || 1)) {
		stroke(255)
		push()
		translate(width / 2 - 400, height - 100)
		rotate(j)
		line(-30, 0, 30, 0)
		line(-30, 0, -20, 5)
		line(-30, 0, -20, -5)
		pop()
	}

	if (turning) {
		fill(255, 100)
	} else {
		noFill()
	}
ellipse(width / 2 + 400, height - 100, 100)
	noFill()
arc(width / 2 + 400, height - 100, 50, 50, 0, PI+PI/2)
push()
translate(width / 2 + 400+cos(PI+PI/2)*25, height - 100+sin(PI+PI/2)*25 )
line(-5, 10, 0, 0)
line(-10, -5, 0, 0)
pop()

 ellipse(width / 2 - 400, + 100, 100)
	noStroke()
	fill(255)
 text('maj', width / 2 - 430, + 100)
text('min', width / 2 - 390, + 100)

noStroke()
	fill(255, 100)
if(minor){
	arc(width / 2 - 400, + 100, 100, 100, -PI/2, PI/2)
} else{
	arc(width / 2 - 400, + 100, 100, 100, PI/2, -PI/2)
}
stroke(255)
	noFill()
ellipse( width / 2 + 400, + 100, 100)	
	fill(255)
noStroke()
text('high', width/2+390, +80)
text('low', width/2+392, +120)

	noStroke()
	fill(255, 100)
	if(highOctave){
		arc(width / 2 + 400, + 100, 100, 100, -PI, 0)
	}else{
		arc(width / 2 + 400, + 100, 100, 100, 0, PI)
	}



}

class oscil {
	constructor(angle, f) {
		this.theta = angle
		this.Otheta = angle
		this.x = width / 2 + cos(angle) * s / 2.1
		this.y = height / 2 + sin(angle) * s / 2.1
		this.rx = this.x
		this.ry = this.y
		this.color = f - 1
		this.color2 = f % 8
		this.sound = new p5.SinOsc
		this.f=f

	}

	key(){
		if (this.f == 1) {
			//is c
			this.freq = 261.63
		}
		if (this.f == 2) {
			//is d
			this.freq = 293.66
		}
		if (this.f == 3) {
			//is e
			if(minor){
				this.freq=311.13
			}else{
			this.freq = 329.63
			}
		}
		if (this.f == 4) {
			//is f
			this.freq = 349.23
		}
		if (this.f == 5) {
			//is g
			this.freq = 392.00
		}
		if (this.f == 6) {
			//is a
			if(minor){
				this.freq = 415.30
			}else{
			this.freq = 440.00
			}
		}
		if (this.f == 7) {
			//is b
			if(minor){
				this.freq= 466.16
			}else{
			this.freq = 493.88
			}
		}
		if (this.f == 8) {
			//is c
			this.freq = 523.25
		}


	}

	move() {
		if (pulsing) {
			let radius = sin(frameCount / 10) * s / 2
			this.x = width / 2 + cos(this.theta) * radius
			this.y = height / 2 + sin(this.theta) * radius

		} else {
			this.x = width / 2 + cos(this.theta) * s / 2.1
			this.y = height / 2 + sin(this.theta) * s / 2.1
		}
		if (turning) {
			this.theta += 0.025
		} else {
			this.theta = this.Otheta
		}

	}


	show() {
		noFill()
		strokeWeight(1)
		stroke(0)
		if (dist((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), this.x, this.y) < s / 2) {
			noStroke()
			fill(255)
			coloring = drawingContext.createRadialGradient(this.x, this.y, 1, this.x, this.y, s)
			let color1 = color(colors[this.color])
			color1.setAlpha(100)
			coloring.addColorStop(0, color1)
			coloring.addColorStop(1, colors[this.color2])
			drawingContext.fillStyle = coloring

		} else {
			stroke(255)
			noFill()
		}
		ellipse(this.x, this.y, s)
		noFill()
	}

	play() {
		if (dist((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), this.x, this.y) < s / 2) {
			this.sound.freq(this.freq *(octave), 0.01);
			this.sound.amp(1, 0.03);
		} else {
			this.sound.amp(0, 0.03);
			this.playing = false;
		}

	}
}

function mousePressed() {
	for (let i = 0; i < oscils.length; i++) {
		oscils[i].sound.start()
	}
	if (dist((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), width / 2 - 400, height - 100) < 50) {
		pulsing = !pulsing
	}
	if(dist((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), width / 2 + 400, height - 100)<50){
		turning= !turning
	}
	if(dist((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), width / 2 - 400, + 100)<50){
		minor= !minor
	}
	if(dist((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), width / 2 + 400, + 100)<50){
		highOctave= !highOctave
	}

}
